	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"credit_note_id" uuid NOT NULL,
	"invoice_id" uuid,
	"opening_balance_id" uuid,
	"amount" numeric(20, 4) NOT NULL,
	"allocated_on" date NOT NULL,
	"journal_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" uuid NOT NULL,
	CONSTRAINT "credit_note_allocations_tenant_id_id_key" UNIQUE("tenant_id","id"),
	CONSTRAINT "credit_note_allocations_one_target" CHECK (("credit_note_allocations"."invoice_id" is null) <> ("credit_note_allocations"."opening_balance_id" is null)),
	CONSTRAINT "credit_note_allocations_not_itself" CHECK ("credit_note_allocations"."invoice_id" is distinct from "credit_note_allocations"."credit_note_id"),
	CONSTRAINT "credit_note_allocations_amount_sane" CHECK ("credit_note_allocations"."amount" > 0 and "credit_note_allocations"."amount" < 1e16)
);
