CREATE POLICY credit_note_allocations_select ON public.credit_note_allocations FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager')
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = credit_note_allocations.tenant_id AND d.id = credit_note_allocations.credit_note_id)
    AND CASE WHEN invoice_id IS NOT NULL
          THEN EXISTS (SELECT 1 FROM public.sales_documents i WHERE i.tenant_id = credit_note_allocations.tenant_id AND i.id = credit_note_allocations.invoice_id)
          ELSE (SELECT app.tenant_branch_ids()) IS NULL END
  );
