-- ── hand-written: credit notes join the sales documents ─────────────────────────────────────────
-- Who may start a sales document, written out again with one more kind: a credit note, which
-- the owner, an accountant or the sales manager writes (the founder's decision, 2026-11-14: a
-- salesperson asks one of them). Everything else is as drizzle/0018_sales_invoices.sql left it.
DROP POLICY sales_documents_insert ON public.sales_documents;
--> statement-breakpoint
CREATE POLICY sales_documents_insert ON public.sales_documents FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND ((SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager')
      OR ((SELECT app.tenant_role()) = 'salesperson' AND kind <> 'credit_note')
      OR ((SELECT app.tenant_role()) = 'warehouse_manager' AND kind = 'delivery'))
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
    AND kind IN ('quotation', 'order', 'delivery', 'invoice', 'credit_note')
    AND status = 'draft'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
-- The guard of a sales document and the guard of its lines, written out again with what a
-- credit note adds. A credit note is made from a posted invoice of the same customer and
-- warehouse; only the owner, an accountant or the sales manager writes it; it is posted only by
-- app.post_credit_note below, which alone can write the mark the guard asks for; it takes a CN
-- number; it carries tax as its invoice did; and once posted it is never cancelled. Each of its
-- lines is a line of that invoice in everything but how much, and says how much came back
-- damaged. Everything else is as it was.
CREATE OR REPLACE FUNCTION app.check_sales_document() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_me uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_filed uuid;
  v_branch uuid;
  v_base text;
  v_registered boolean;
  v_inclusive boolean;
  v_lines integer;
  v_gross numeric;
  v_discount numeric;
  v_value numeric;
  v_tax numeric;
  v_further numeric;
  v_extra numeric;
  v_total numeric;
  v_limit numeric;
  v_receivable numeric;
  v_orders numeric;
  v_over boolean := false;
  v_customer public.customers%ROWTYPE;
  v_address text;
  v_changes jsonb;
  v_what jsonb;
  -- What submitting, holding and cancelling may change; everything else stays as it stood.
  v_moves text[] := ARRAY['status', 'number', 'submitted_at', 'submitted_by',
    'buyer_name', 'buyer_ntn', 'buyer_cnic', 'buyer_strn', 'buyer_registration_type', 'buyer_atl_status', 'buyer_province', 'buyer_address',
    'credit_limit', 'credit_exposure', 'credit_override_reason', 'credit_override_by', 'held_at', 'held_by',
    'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by', 'posted_txid'];
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  -- Every check below reads what is committed now. A transaction that reads an older picture
  -- of the database could slip a line or a second order past them, so it is not let in.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    -- A credit note is written by the owner, an accountant or the sales manager; a salesperson asks one of them.
    IF NOT app.writes_sales_document(v_role, v_scope, v_me, OLD.branch_id, OLD.created_by, OLD.salesperson_id, OLD.kind)
       OR (OLD.kind = 'credit_note' AND v_role NOT IN ('owner', 'accountant', 'sales_manager')) THEN
      RAISE EXCEPTION 'not a sales document this member may write' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'only a draft is thrown away; a submitted document is cancelled' USING ERRCODE = 'SE050';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Who may write the row is asked here as well as by the policies, for this row and at this
  -- moment: the policies read the company and the role once per statement, each on its own.
  IF NEW.updated_by IS DISTINCT FROM v_me
     OR NOT app.writes_sales_document(v_role, v_scope, v_me, NEW.branch_id, NEW.created_by, NEW.salesperson_id, NEW.kind)
     OR (TG_OP = 'UPDATE' AND NOT app.writes_sales_document(v_role, v_scope, v_me, OLD.branch_id, OLD.created_by, OLD.salesperson_id, OLD.kind))
     OR (TG_OP = 'INSERT' AND NEW.created_by IS DISTINCT FROM v_me)
     OR (NEW.kind = 'credit_note' AND v_role NOT IN ('owner', 'accountant', 'sales_manager')) THEN
    RAISE EXCEPTION 'not a sales document this member may write' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();
  SELECT w.branch_id INTO v_branch FROM public.warehouses w WHERE w.tenant_id = NEW.tenant_id AND w.id = NEW.warehouse_id;
  IF FOUND AND v_branch IS DISTINCT FROM NEW.branch_id THEN
    RAISE EXCEPTION 'a document belongs to the branch of its warehouse' USING ERRCODE = 'SE052';
  END IF;
  -- Until foreign-currency sales exist, every document is in the base currency at a rate of one.
  -- A rate left free would let an order weigh next to nothing against the credit limit.
  SELECT c.code INTO v_base FROM public.currencies c WHERE c.tenant_id = NEW.tenant_id AND c.is_base;
  IF NEW.currency IS DISTINCT FROM v_base OR NEW.exchange_rate <> 1 THEN
    RAISE EXCEPTION 'a sales document is in the company''s base currency' USING ERRCODE = 'SE052';
  END IF;
  -- A delivery note is made from one sales order: for its customer, from its warehouse. Nothing
  -- else has a source yet.
  IF NEW.kind = 'delivery' THEN
    -- The order must be one the writer may see: a salesperson delivers their own orders, not a
    -- colleague's. The note is filed under whoever the order is filed under, or failing that
    -- whoever wrote it, so the people who see the order see its delivery notes.
    SELECT coalesce(o.salesperson_id, o.created_by) INTO v_filed FROM public.sales_documents o
      WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'order'
        AND o.customer_id = NEW.customer_id AND o.warehouse_id = NEW.warehouse_id
        AND (TG_OP <> 'INSERT' OR o.status = 'submitted')
        AND (v_role <> 'salesperson' OR o.created_by = v_me OR o.salesperson_id IS NOT DISTINCT FROM v_me);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'a delivery note is made from a submitted sales order, for its customer, from its warehouse' USING ERRCODE = 'SE066';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.salesperson_id := v_filed;
    ELSIF OLD.status = 'draft' THEN
      NEW.salesperson_id := v_filed;
    END IF;
  ELSIF NEW.kind = 'invoice' THEN
    -- A sales invoice is made from a posted delivery note, which it bills, or from a sales
    -- order, which it delivers and bills at once: for the same customer, from the same
    -- warehouse, and one the writer may see. It is filed under whoever its source is.
    SELECT coalesce(o.salesperson_id, o.created_by) INTO v_filed FROM public.sales_documents o
      WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind IN ('order', 'delivery')
        AND o.customer_id = NEW.customer_id AND o.warehouse_id = NEW.warehouse_id
        AND (TG_OP <> 'INSERT' OR o.status = 'submitted')
        AND (v_role <> 'salesperson' OR o.created_by = v_me OR o.salesperson_id IS NOT DISTINCT FROM v_me);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'a sales invoice is made from a submitted sales order or a posted delivery note, for its customer, from its warehouse' USING ERRCODE = 'SE066';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.salesperson_id := v_filed;
    ELSIF OLD.status = 'draft' THEN
      NEW.salesperson_id := v_filed;
    END IF;
  ELSIF NEW.kind = 'credit_note' THEN
    -- A credit note takes back part of one posted sales invoice: for the same customer, into
    -- the warehouse the goods left from. It is filed under whoever the invoice is filed under,
    -- so the salesperson whose sale it was sees it.
    SELECT coalesce(o.salesperson_id, o.created_by) INTO v_filed FROM public.sales_documents o
      WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'invoice' AND o.status = 'submitted'
        AND o.customer_id = NEW.customer_id AND o.warehouse_id = NEW.warehouse_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'a credit note is made from a posted sales invoice, for its customer, into its warehouse' USING ERRCODE = 'SE113';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.salesperson_id := v_filed;
    ELSIF OLD.status = 'draft' THEN
      NEW.salesperson_id := v_filed;
    END IF;
  ELSIF NEW.source_document_id IS NOT NULL THEN
    RAISE EXCEPTION 'only a delivery note, a sales invoice or a credit note is made from another document' USING ERRCODE = 'SE052';
  END IF;
  -- The day an invoice falls due is worked out when it is posted, here; until then there is none.
  IF NEW.status IN ('draft', 'on_hold') THEN
    NEW.due_date := NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a document starts as a draft' USING ERRCODE = 'SE050';
    END IF;
    IF NEW.kind NOT IN ('quotation', 'order', 'delivery', 'invoice', 'credit_note') THEN
      RAISE EXCEPTION 'that kind of sales document cannot be written yet' USING ERRCODE = 'SE050';
    END IF;
    -- A draft carries nothing that only submitting, approving or FBR may write.
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    NEW.buyer_address := NULL;
    NEW.fbr_invoice_number := NULL;
    NEW.fbr_submission_id := NULL;
    NEW.fbr_status := NULL;
    NEW.offline_flag := false;
    -- Only the posting functions say a document was posted by them.
    NEW.posted_txid := NULL;
    RETURN NEW;
  END IF;

  IF NEW.kind <> OLD.kind OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at OR NEW.source_document_id IS DISTINCT FROM OLD.source_document_id THEN
    RAISE EXCEPTION 'what a document is, what it was made from and who wrote it never change' USING ERRCODE = 'SE050';
  END IF;
  IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    NEW.buyer_address := NULL;
    RETURN NEW;
  END IF;
  IF OLD.status IN ('submitted', 'cancelled') AND NOT (OLD.status = 'submitted' AND NEW.status = 'cancelled') THEN
    RAISE EXCEPTION 'a submitted document is never changed; cancel it instead' USING ERRCODE = 'SE050';
  END IF;
  IF NOT ((OLD.status = 'draft' AND NEW.status IN ('on_hold', 'submitted')) OR (OLD.status = 'on_hold' AND NEW.status IN ('draft', 'submitted')) OR (OLD.status = 'submitted' AND NEW.status = 'cancelled')) THEN
    RAISE EXCEPTION 'a sales document cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'SE050';
  END IF;
  -- From here on the document moves on, and moves on as it stands.
  IF (to_jsonb(NEW) - v_moves) IS DISTINCT FROM (to_jsonb(OLD) - v_moves) THEN
    RAISE EXCEPTION 'a document is submitted, held, sent back or cancelled as it stands' USING ERRCODE = 'SE052';
  END IF;

  IF NEW.status = 'draft' THEN
    -- Sent back, or taken back: it is a draft again and can be changed.
    NEW.held_at := NULL;
    NEW.held_by := NULL;
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    NEW.buyer_address := NULL;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_order.release', 'sales_document', NEW.id, jsonb_build_object('status', 'on_hold'), jsonb_build_object('status', 'draft'));
    RETURN NEW;
  END IF;

  IF NEW.status = 'cancelled' THEN
    IF NEW.cancelled_by IS DISTINCT FROM v_me THEN
      RAISE EXCEPTION 'a document is cancelled in the name of whoever cancels it' USING ERRCODE = 'SE052';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'cancelled_at', 'cancelled_by', 'cancel_reason', 'updated_at', 'updated_by']) THEN
      RAISE EXCEPTION 'a submitted document is never changed; cancel it instead' USING ERRCODE = 'SE050';
    END IF;
    -- Goods that have left against an order keep the order alive: the delivery notes are cancelled first.
    IF OLD.kind = 'order' AND EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = OLD.tenant_id AND d.source_document_id = OLD.id AND d.kind IN ('delivery', 'invoice') AND d.status = 'submitted'
    ) THEN
      RAISE EXCEPTION 'an order with goods delivered or invoiced is not cancelled' USING ERRCODE = 'SE065';
    END IF;
    -- A delivery note that has been billed stays: the invoice says what it delivered.
    IF OLD.kind = 'delivery' AND EXISTS (
      SELECT 1 FROM public.sales_documents i
      WHERE i.tenant_id = OLD.tenant_id AND i.source_document_id = OLD.id AND i.kind = 'invoice' AND i.status = 'submitted'
    ) THEN
      RAISE EXCEPTION 'a delivery note that has been invoiced is not cancelled' USING ERRCODE = 'SE073';
    END IF;
    -- A posted invoice is in the books and with the customer: it is corrected by a credit note.
    IF OLD.kind = 'invoice' THEN
      RAISE EXCEPTION 'a posted sales invoice is not cancelled; it is corrected by a credit note' USING ERRCODE = 'SE072';
    END IF;
    -- So is a posted credit note: it is never cancelled.
    IF OLD.kind = 'credit_note' THEN
      RAISE EXCEPTION 'a posted credit note is not cancelled' USING ERRCODE = 'SE116';
    END IF;
    NEW.cancelled_at := now();
    NEW.cancel_reason := btrim(NEW.cancel_reason);
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_' || NEW.kind || '.cancel', 'sales_document', NEW.id,
        jsonb_build_object('number', OLD.number, 'status', 'submitted'), jsonb_build_object('number', OLD.number, 'status', 'cancelled', 'reason', NEW.cancel_reason));
    RETURN NEW;
  END IF;

  -- A credit note is posted by the database's own function and by nothing else. Only that
  -- function can write the mark, and it checks every figure against the invoice before it does.
  IF NEW.kind = 'credit_note' AND (NEW.status <> 'submitted' OR NEW.posted_txid IS DISTINCT FROM txid_current()) THEN
    RAISE EXCEPTION 'a credit note is posted only by the database''s own posting function' USING ERRCODE = 'SE117';
  END IF;

  -- Held or submitted: the document must be whole.
  SELECT count(*), coalesce(sum(round(l.quantity * l.unit_price, 2)), 0), coalesce(sum(l.discount_amount), 0), coalesce(sum(l.value), 0),
         coalesce(sum(l.tax_amount), 0), coalesce(sum(l.further_tax_amount), 0), coalesce(sum(l.extra_tax_amount), 0), coalesce(sum(l.total), 0)
    INTO v_lines, v_gross, v_discount, v_value, v_tax, v_further, v_extra, v_total
    FROM public.sales_lines l WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'a document needs at least one line' USING ERRCODE = 'SE052';
  END IF;
  IF NEW.gross_total <> v_gross OR NEW.discount_total <> v_discount OR NEW.value_total <> v_value OR NEW.tax_total <> v_tax
     OR NEW.further_tax_total <> v_further OR NEW.extra_tax_total <> v_extra OR NEW.total <> v_total THEN
    RAISE EXCEPTION 'the totals of a document are those of its lines' USING ERRCODE = 'SE052';
  END IF;
  -- Each line is its quantity at its price, less its discount: before tax, or with the tax inside.
  -- (A line of a credit note comes to a share of the invoice line it takes back; the posting
  -- function has checked it.)
  IF NEW.kind <> 'credit_note' AND EXISTS (
    SELECT 1 FROM public.sales_lines l
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id
      AND (CASE WHEN NEW.prices_include_tax THEN l.total - l.extra_tax_amount ELSE l.value END) <> round(l.quantity * l.unit_price, 2) - l.discount_amount
  ) THEN
    RAISE EXCEPTION 'a line comes to its quantity at its price, less its discount' USING ERRCODE = 'SE052';
  END IF;
  -- Whether the document carries sales tax, and whether its prices hold the tax, is the company's answer, not the writer's.
  SELECT s.sales_tax_registered, s.sales_tax_registered AND s.prices_include_tax INTO v_registered, v_inclusive
    FROM public.company_setup s WHERE s.tenant_id = NEW.tenant_id;
  -- A credit note carries tax as its invoice did, whatever the company has become since.
  IF NEW.kind = 'credit_note' THEN
    SELECT i.taxed, i.prices_include_tax INTO v_registered, v_inclusive FROM public.sales_documents i
      WHERE i.tenant_id = NEW.tenant_id AND i.id = NEW.source_document_id;
  END IF;
  IF NEW.taxed IS DISTINCT FROM coalesce(v_registered, false) OR NEW.prices_include_tax IS DISTINCT FROM coalesce(v_inclusive, false) THEN
    RAISE EXCEPTION 'a document carries sales tax as the company is registered for it' USING ERRCODE = 'SE052';
  END IF;
  IF NOT NEW.taxed AND EXISTS (
    SELECT 1 FROM public.sales_lines l
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id
      AND (l.tax_amount <> 0 OR l.further_tax_amount <> 0 OR l.extra_tax_amount <> 0 OR l.tax_rate <> 0 OR l.further_tax_rate <> 0 OR l.tax_kind IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'a document without sales tax has no tax on its lines' USING ERRCODE = 'SE052';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sales_line_salespeople s
    WHERE s.tenant_id = NEW.tenant_id AND s.document_id = NEW.id
    GROUP BY s.line_id HAVING sum(s.share_percent) <> 100
  ) OR (NEW.kind <> 'invoice' AND EXISTS (
    SELECT 1 FROM public.sales_line_salespeople s
    WHERE s.tenant_id = NEW.tenant_id AND s.document_id = NEW.id
      AND NOT EXISTS (SELECT 1 FROM public.memberships m WHERE m.tenant_id = s.tenant_id AND m.user_id = s.user_id AND m.active AND m.role IN ('owner', 'sales_manager', 'salesperson'))
  )) THEN
    RAISE EXCEPTION 'the salespeople''s shares of a line come to 100, among active members of the sales team' USING ERRCODE = 'SE052';
  END IF;
  IF NEW.kind = 'delivery' AND NOT EXISTS (
    SELECT 1 FROM public.sales_documents o
    WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'order' AND o.status = 'submitted' AND o.document_date <= NEW.document_date
  ) THEN
    RAISE EXCEPTION 'a delivery note is posted against a submitted sales order, on or after its date' USING ERRCODE = 'SE066';
  END IF;
  IF NEW.kind = 'invoice' AND NOT EXISTS (
    SELECT 1 FROM public.sales_documents o
    WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind IN ('order', 'delivery') AND o.status = 'submitted' AND o.document_date <= NEW.document_date
  ) THEN
    RAISE EXCEPTION 'a sales invoice is posted against a submitted sales order or a posted delivery note, on or after its date' USING ERRCODE = 'SE066';
  END IF;
  IF NEW.kind = 'credit_note' AND NOT EXISTS (
    SELECT 1 FROM public.sales_documents o
    WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'invoice' AND o.status = 'submitted' AND o.document_date <= NEW.document_date
  ) THEN
    RAISE EXCEPTION 'a credit note is posted against a posted sales invoice, on or after its date' USING ERRCODE = 'SE113';
  END IF;
  SELECT c.* INTO v_customer FROM public.customers c WHERE c.tenant_id = NEW.tenant_id AND c.id = NEW.customer_id;
  -- Goods already delivered are billed even if the customer has been archived since; and goods
  -- already billed are taken back.
  IF v_customer.archived_at IS NOT NULL AND NEW.kind <> 'credit_note' AND NOT (NEW.kind = 'invoice' AND EXISTS (
    SELECT 1 FROM public.sales_documents o WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_document_id AND o.kind = 'delivery'
  )) THEN
    RAISE EXCEPTION 'the customer is archived' USING ERRCODE = 'SE052';
  END IF;

  IF NEW.kind = 'order' THEN
    -- One order at a time per customer, so two cannot both fit under the same limit.
    PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || NEW.tenant_id::text || ':' || NEW.customer_id::text, 0));
    SELECT k.credit_limit, k.receivable, k.open_orders INTO v_limit, v_receivable, v_orders FROM app.customer_credit(NEW.customer_id, NEW.id) k;
    v_over := v_limit IS NOT NULL AND v_receivable + v_orders + NEW.total > v_limit;
  END IF;
  v_what := jsonb_build_object('kind', NEW.kind, 'customer', v_customer.name, 'date', NEW.document_date, 'lines', v_lines, 'total', NEW.total::text);

  IF NEW.status = 'on_hold' THEN
    IF NOT v_over THEN
      RAISE EXCEPTION 'only an order over its customer''s credit limit waits for approval' USING ERRCODE = 'SE054';
    END IF;
    IF NEW.held_by IS DISTINCT FROM v_me THEN
      RAISE EXCEPTION 'an order is held in the name of whoever holds it' USING ERRCODE = 'SE052';
    END IF;
    NEW.held_at := now();
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_order.hold', 'sales_document', NEW.id,
        v_what || jsonb_build_object('creditLimit', v_limit::text, 'owed', v_receivable::text, 'otherOrders', v_orders::text));
    RETURN NEW;
  END IF;

  -- Submitted. Who submitted it, when, to whom and under what number are the database's own answers.
  IF NEW.submitted_by IS DISTINCT FROM v_me THEN
    RAISE EXCEPTION 'a document is submitted in the name of whoever submits it' USING ERRCODE = 'SE052';
  END IF;
  SELECT nullif(concat_ws(', ', a.line, a.city), '') INTO v_address FROM public.party_addresses a
    WHERE a.tenant_id = NEW.tenant_id AND a.customer_id = NEW.customer_id AND a.is_primary;
  NEW.buyer_name := v_customer.name;
  NEW.buyer_ntn := v_customer.ntn;
  NEW.buyer_cnic := v_customer.cnic;
  NEW.buyer_strn := v_customer.strn;
  NEW.buyer_registration_type := v_customer.registration_type::text;
  NEW.buyer_atl_status := v_customer.atl_status::text;
  NEW.buyer_province := v_customer.province::text;
  NEW.buyer_address := v_address;
  NEW.submitted_at := now();
  NEW.held_at := NULL;
  NEW.held_by := NULL;
  -- An invoice falls due after the customer's credit days, counted from its own date.
  IF NEW.kind = 'invoice' THEN
    NEW.due_date := NEW.document_date + coalesce(v_customer.credit_days, 0);
  END IF;
  IF NEW.kind = 'order' THEN
    NEW.credit_limit := v_limit;
    NEW.credit_exposure := v_receivable + v_orders;
  ELSE
    NEW.credit_limit := NULL;
    NEW.credit_exposure := NULL;
  END IF;
  IF v_over THEN
    IF v_role IS DISTINCT FROM 'owner' THEN
      RAISE EXCEPTION 'the order takes the customer over the credit limit; only an owner approves it' USING ERRCODE = 'SE051';
    END IF;
    IF NEW.credit_override_reason IS NULL THEN
      RAISE EXCEPTION 'an order over the credit limit is approved with a reason' USING ERRCODE = 'SE053';
    END IF;
    NEW.credit_override_reason := btrim(NEW.credit_override_reason);
    NEW.credit_override_by := v_me;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, v_me, v_role, 'sales_order.credit_override', 'sales_document', NEW.id,
        jsonb_build_object('creditLimit', v_limit::text, 'owed', v_receivable::text, 'otherOrders', v_orders::text),
        jsonb_build_object('orderTotal', NEW.total::text, 'over', (v_receivable + v_orders + NEW.total - v_limit)::text, 'reason', NEW.credit_override_reason));
  ELSE
    NEW.credit_override_reason := NULL;
    NEW.credit_override_by := NULL;
  END IF;
  -- The number comes from the series here and nowhere else, so it cannot be invented, and a
  -- date with no open fiscal period is refused (SE001, SE002).
  NEW.number := app.next_document_number(CASE NEW.kind WHEN 'quotation' THEN 'QT' WHEN 'order' THEN 'SO' WHEN 'delivery' THEN 'DN' WHEN 'invoice' THEN 'SI' WHEN 'credit_note' THEN 'CN' ELSE '??' END, NEW.document_date);
  -- Every line sold at a price that is not the price lists', or with a discount, is named in the log.
  SELECT jsonb_agg(jsonb_build_object('item', l.description, 'list', l.list_price::text, 'charged', l.unit_price::text,
           'discount', CASE WHEN l.discount_percent IS NOT NULL THEN trim_scale(l.discount_percent)::text || '%' WHEN l.discount_amount <> 0 THEN l.discount_amount::text END) ORDER BY l.line_no)
    INTO v_changes
    FROM public.sales_lines l
    WHERE l.tenant_id = NEW.tenant_id AND l.document_id = NEW.id AND (l.discount_percent IS NOT NULL OR l.discount_amount <> 0 OR l.list_price IS DISTINCT FROM l.unit_price);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (NEW.tenant_id, v_me, v_role, 'sales_' || NEW.kind || '.submit', 'sales_document', NEW.id,
      jsonb_build_object('number', NEW.number) || v_what || CASE WHEN v_changes IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('priceChanges', v_changes) END);
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.check_sales_document_part() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid;
  v_document uuid;
  v_status text;
  v_branch uuid;
  v_created_by uuid;
  v_salesperson uuid;
  v_kind text;
  v_source uuid;
  -- What a line of a credit note does not share with the invoice line it takes back.
  v_own text[] := ARRAY['id', 'document_id', 'line_no', 'quantity', 'base_quantity', 'discount_amount', 'tax_amount', 'further_tax_amount',
    'extra_tax_amount', 'value', 'total', 'source_line_id', 'damaged_quantity', 'returned_cost', 'created_at', 'created_by'];
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
    IF TG_TABLE_NAME = 'sales_document_links' THEN
      v_document := OLD.to_document_id;
    ELSE
      v_document := OLD.document_id;
    END IF;
  ELSE
    v_tenant := NEW.tenant_id;
    IF TG_TABLE_NAME = 'sales_document_links' THEN
      v_document := NEW.to_document_id;
    ELSE
      v_document := NEW.document_id;
    END IF;
  END IF;
  IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- As for the document itself: a transaction reading an older picture could add a line to a
  -- document that has since been submitted.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  SELECT d.status, d.branch_id, d.created_by, d.salesperson_id, d.kind, d.source_document_id INTO v_status, v_branch, v_created_by, v_salesperson, v_kind, v_source FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = v_document
    FOR SHARE;
  -- The document must be one this member may write, asked for this row and at this moment.
  IF FOUND AND (NOT app.writes_sales_document(app.tenant_role(), app.tenant_branch_ids(), app.current_user_id(), v_branch, v_created_by, v_salesperson, v_kind)
                OR (v_kind = 'credit_note' AND app.tenant_role() NOT IN ('owner', 'accountant', 'sales_manager'))) THEN
    RAISE EXCEPTION 'not a sales document this member may write' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF FOUND AND v_status <> 'draft' THEN
    RAISE EXCEPTION 'a submitted document is never changed; cancel it instead' USING ERRCODE = 'SE050';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  NEW.created_at := now();
  IF TG_TABLE_NAME = 'sales_lines' THEN
    -- What returned goods cost is the posting function's to say: a line is written without it.
    IF TG_OP = 'INSERT' THEN
      NEW.returned_cost := NULL;
    END IF;
    IF v_kind IS DISTINCT FROM 'credit_note' AND NEW.damaged_quantity IS NOT NULL THEN
      RAISE EXCEPTION 'only a line of a credit note says how much came back damaged' USING ERRCODE = 'SE120';
    END IF;
    -- (A line of a credit note is in the unit its invoice line was sold in, whatever has
    -- become of the item's units since: the goods come back as they left.)
    IF v_kind IS DISTINCT FROM 'credit_note' AND NOT EXISTS (
      SELECT 1 FROM public.items i
      WHERE i.tenant_id = NEW.tenant_id AND i.id = NEW.item_id
        AND ((i.base_unit_id = NEW.unit_id AND NEW.unit_factor = 1)
          OR EXISTS (SELECT 1 FROM public.item_units u WHERE u.tenant_id = i.tenant_id AND u.item_id = i.id AND u.unit_id = NEW.unit_id AND u.factor = NEW.unit_factor))
    ) THEN
      RAISE EXCEPTION 'a line is sold in one of its item''s own units' USING ERRCODE = 'SE052';
    END IF;
    -- A discount is its percentage of the quantity at the price, to the paisa, and nothing else:
    -- an amount typed beside a percentage could make a line bill anything from nil to the full price.
    IF v_kind IS DISTINCT FROM 'credit_note' AND NEW.discount_amount <> (CASE WHEN NEW.discount_percent IS NULL THEN 0 ELSE round(round(NEW.quantity * NEW.unit_price, 2) * NEW.discount_percent / 100, 2) END) THEN
      RAISE EXCEPTION 'a line''s discount is its percentage of the quantity at the price' USING ERRCODE = 'SE052';
    END IF;
    -- A line of a delivery note delivers one line of the note's own order: the same item, in the
    -- same unit. No other kind of document has a source line yet.
    IF v_kind = 'delivery' THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.sales_lines o
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_line_id AND o.document_id = v_source
          AND o.item_id = NEW.item_id AND o.unit_id = NEW.unit_id AND o.unit_factor = NEW.unit_factor
          AND o.unit_price = NEW.unit_price AND o.discount_percent IS NOT DISTINCT FROM NEW.discount_percent
          AND o.list_price IS NOT DISTINCT FROM NEW.list_price AND o.price_source IS NOT DISTINCT FROM NEW.price_source
      ) THEN
        RAISE EXCEPTION 'a line of a delivery note delivers a line of its order, in the same unit and at the order''s price' USING ERRCODE = 'SE052';
      END IF;
      -- Tax belongs to the invoice: a delivery note values the goods and nothing more.
      IF NEW.tax_amount <> 0 OR NEW.further_tax_amount <> 0 OR NEW.extra_tax_amount <> 0 OR NEW.tax_rate <> 0 OR NEW.further_tax_rate <> 0
         OR NEW.tax_kind IS NOT NULL OR NEW.tax_category_id IS NOT NULL THEN
        RAISE EXCEPTION 'a delivery note carries no tax' USING ERRCODE = 'SE052';
      END IF;
    ELSIF v_kind = 'invoice' THEN
      -- A line of an invoice bills one line of what the invoice was made from: the same item,
      -- in the same unit, at its price and discount. The tax is the invoice's own.
      IF NOT EXISTS (
        SELECT 1 FROM public.sales_lines o
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_line_id AND o.document_id = v_source
          AND o.item_id = NEW.item_id AND o.unit_id = NEW.unit_id AND o.unit_factor = NEW.unit_factor
          AND o.unit_price = NEW.unit_price AND o.discount_percent IS NOT DISTINCT FROM NEW.discount_percent
          AND o.list_price IS NOT DISTINCT FROM NEW.list_price AND o.price_source IS NOT DISTINCT FROM NEW.price_source
      ) THEN
        RAISE EXCEPTION 'a line of a sales invoice bills a line of what it was made from, in the same unit and at its price' USING ERRCODE = 'SE052';
      END IF;
    ELSIF v_kind = 'credit_note' THEN
      -- A line of a credit note takes back part of one line of the note's own invoice, and is
      -- that line in everything but how much: the same item, unit, price, discount and tax
      -- rates. It says how much of what came back is damaged, in a quantity the item's own unit
      -- can hold. What it comes to is checked against the invoice when the credit note is posted.
      IF NEW.damaged_quantity IS NULL OR NEW.damaged_quantity * NEW.unit_factor <> round(NEW.damaged_quantity * NEW.unit_factor, 4) OR NOT EXISTS (
        SELECT 1 FROM public.sales_lines o
        WHERE o.tenant_id = NEW.tenant_id AND o.id = NEW.source_line_id AND o.document_id = v_source
          AND o.quantity >= NEW.quantity
          AND (to_jsonb(o) - v_own) = (to_jsonb(NEW) - v_own)
      ) THEN
        RAISE EXCEPTION 'a line of a credit note takes back part of a line of its invoice, as that line was billed' USING ERRCODE = 'SE120';
      END IF;
    ELSIF NEW.source_line_id IS NOT NULL THEN
      RAISE EXCEPTION 'only a line of a delivery note, a sales invoice or a credit note follows another line' USING ERRCODE = 'SE052';
    END IF;
  ELSIF TG_TABLE_NAME = 'sales_line_salespeople' THEN
    -- A credit note has no shares of its own: a returned line's are those of the invoice line it takes back.
    IF v_kind = 'credit_note' THEN
      RAISE EXCEPTION 'a credit note carries no salespeople of its own' USING ERRCODE = 'SE120';
    END IF;
    -- An invoice's shares are its order's, copied by the posting function; whoever has left the sales team since still has theirs.
    IF v_kind <> 'invoice' AND NOT EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.tenant_id = NEW.tenant_id AND m.user_id = NEW.user_id AND m.active AND m.role IN ('owner', 'sales_manager', 'salesperson')
    ) THEN
      RAISE EXCEPTION 'a share of a sale goes to an active member of the sales team' USING ERRCODE = 'SE052';
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint

-- ── hand-written: the lists the whole app shares ────────────────────────────────────────────────
-- Each added with a function of this step's own, as drizzle/0019_journal_documents.sql says.
-- (Credit notes already take a number: CN is among the kinds the product numbers.)

-- A credit note's journal stands with the posted credit note it names. It is never reversed:
-- it has no function for a reversal, so one is refused.
CREATE FUNCTION app.journal_backed_credit_note(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = p_journal.tenant_id AND d.id = p_journal.source_id AND d.kind = 'credit_note' AND d.status = 'submitted'
        AND d.number = p_journal.document_number AND d.document_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
-- The journal that sets part of a credit note's credit against an invoice stands with the row
-- that names it. It is never reversed either.
CREATE FUNCTION app.journal_backed_credit_application(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.credit_note_allocations a
      WHERE a.tenant_id = p_journal.tenant_id AND a.id = p_journal.source_id AND a.journal_id = p_journal.id AND a.allocated_on = p_journal.journal_date)
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.journal_backed_credit_note(public.journals), app.journal_backed_credit_application(public.journals) FROM PUBLIC;
--> statement-breakpoint
-- The audit rows only the functions below write: the app's role cannot write a look-alike.
CREATE FUNCTION app.audit_reserved_credit_note(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('credit_note.post', 'credit_note.apply') $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.audit_reserved_credit_note(text) FROM PUBLIC;
--> statement-breakpoint

-- ── hand-written: what is still unpaid on an invoice, with credit notes ─────────────────────────
-- app.receivable_items of drizzle/0022_receipts.sql, written out again with one more thing
-- that settles an invoice: what credit notes have been set against it. It is the one place
-- every question about what is still owed on an invoice is asked, so the receipts, the list of
-- unpaid invoices and the check that nothing is paid twice all follow. Not for the app to call.
CREATE OR REPLACE FUNCTION app.receivable_items(p_tenant uuid, p_customer uuid)
  RETURNS TABLE (kind text, id uuid, number text, document_date date, due_date date, branch_id uuid, total numeric, settled numeric)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT 'invoice'::text, d.id, d.number, d.document_date, coalesce(d.due_date, d.document_date), d.branch_id, d.total,
      coalesce((
        SELECT sum(a.amount) FROM public.receipt_allocations a
        WHERE a.tenant_id = d.tenant_id AND a.invoice_id = d.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL), 0)
      + coalesce((
        SELECT sum(c.amount) FROM public.credit_note_allocations c
        WHERE c.tenant_id = d.tenant_id AND c.invoice_id = d.id), 0)
    FROM public.sales_documents d
    WHERE d.tenant_id = p_tenant AND d.customer_id = p_customer AND d.kind = 'invoice' AND d.status = 'submitted'
    UNION ALL
    SELECT 'opening'::text, b.id, b.document_number, b.document_date, coalesce(b.due_date, b.document_date), NULL::uuid, b.debit,
      coalesce((
        SELECT sum(a.amount) FROM public.receipt_allocations a
        WHERE a.tenant_id = b.tenant_id AND a.opening_balance_id = b.id AND a.posted_at IS NOT NULL AND a.voided_at IS NULL), 0)
      + coalesce((
        SELECT sum(c.amount) FROM public.credit_note_allocations c
        WHERE c.tenant_id = b.tenant_id AND c.opening_balance_id = b.id), 0)
    FROM public.opening_balances b
    JOIN public.opening_entries e ON e.tenant_id = b.tenant_id AND e.id = b.opening_entry_id
    WHERE b.tenant_id = p_tenant AND b.customer_id = p_customer AND b.kind = 'receivable' AND e.status = 'posted'
  $$;
--> statement-breakpoint

-- ── hand-written: what a line of a credit note comes to ─────────────────────────────────────────
-- Not for the app to call. One figure of a line of a credit note (its value, its sales tax, its
-- further tax, its extra tax, or what its goods cost). Every credit note brings what has been
-- taken back of the invoice line's figure up to the figure's exact share for all that has come
-- back so far, rounded to the paisa, half up; this credit note's part is that, less what
-- earlier credit notes took. So however a line comes back, in one credit note or in twenty,
-- what has been credited is never more than half a paisa from the exact share, and the credit
-- notes of a line that has all come back are exactly the line.
--
--   p_whole  the invoice line's figure           p_gone  what earlier credit notes took of it
--   p_upto   the quantity that has come back,    p_of    the quantity invoiced
--            this credit note included
--
-- The rounding is done in whole numbers so that the app, which works the same figure out to
-- show it, cannot differ by a digit: floor((2 * 100 * whole * upto + of) / (2 * of)) / 100.
CREATE FUNCTION app.credit_note_share(p_whole numeric, p_gone numeric, p_upto numeric, p_of numeric) RETURNS numeric
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT CASE WHEN p_upto >= p_of THEN p_whole
                ELSE least(div(p_whole * p_upto * 200 + p_of, 2 * p_of) / 100, p_whole) END - p_gone
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.credit_note_share(numeric, numeric, numeric, numeric) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.credit_note_share(numeric, numeric, numeric, numeric) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: posting a credit note ─────────────────────────────────────────────────────────
-- One act of the database, like posting an invoice. It holds the credit note and its invoice,
-- so two credit notes for one invoice take their turn; checks each line against the invoice
-- line it takes back (no more than is left of what was invoiced, and exactly the share of the
-- line's value and tax that the quantity is); writes on each line what its goods cost when
-- they left (the same share of the cost of the move that took them out of stock); marks the
-- credit note submitted, which takes its CN number, copies the buyer and writes the audit row;
-- puts the goods that can be sold again back into the warehouse they left, at that cost; and
-- posts the journal set out at the top of this file.
--
-- What it takes off the customer's account is first set against its own invoice, as far as
-- that is still unpaid; the rest is the customer's credit, kept with advances from customers
-- until app.apply_credit_note sets it against another invoice.
--
-- Refused: more than was invoiced (SE114), figures that are not the invoice's (SE115), an
-- invoice that is not posted or not this customer's (SE113), a date before the invoice's or
-- that has not come yet (SE113, SE111), a closed period.
CREATE FUNCTION app.post_credit_note(p_document uuid)
  RETURNS TABLE (number text, journal_id uuid, set_against_invoice numeric, left_as_credit numeric)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.sales_documents%ROWTYPE;
  v_invoice public.sales_documents%ROWTYPE;
  v_source_kind text;
  v_line record;
  v_lines integer := 0;
  v_upto numeric;
  v_value numeric;
  v_tax numeric;
  v_further numeric;
  v_extra numeric;
  v_discount numeric;
  v_out_value numeric;
  v_out_quantity numeric;
  v_cost numeric;
  v_cost_damaged numeric;
  v_good numeric;
  v_restocked numeric := 0;
  v_written_off numeric := 0;
  v_outstanding numeric;
  v_applied numeric;
  v_excess numeric;
  v_number text;
  v_journal uuid;
  v_line_no integer := 0;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'sales_manager') THEN
    RAISE EXCEPTION 'this role cannot post a credit note' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  SELECT d.* INTO v_doc FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = p_document AND d.kind = 'credit_note'
    FOR UPDATE;
  -- A credit note outside a member's branches does not exist for that member.
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such credit note in this company' USING ERRCODE = 'SE112';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft credit note is posted' USING ERRCODE = 'SE050';
  END IF;
  -- The invoice is held until the transaction ends: its credit notes take their turn.
  SELECT i.* INTO v_invoice FROM public.sales_documents i
    WHERE i.tenant_id = v_tenant AND i.id = v_doc.source_document_id AND i.kind = 'invoice'
    FOR NO KEY UPDATE;
  IF NOT FOUND OR v_invoice.status <> 'submitted' OR v_invoice.customer_id <> v_doc.customer_id OR v_invoice.warehouse_id <> v_doc.warehouse_id THEN
    RAISE EXCEPTION 'a credit note is posted against a posted sales invoice, for its customer, into its warehouse' USING ERRCODE = 'SE113';
  END IF;
  IF v_doc.document_date < v_invoice.document_date THEN
    RAISE EXCEPTION 'a credit note is dated on or after its invoice' USING ERRCODE = 'SE113';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF v_doc.document_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.document_date);
  -- What the customer owes is about to change: receipts, orders and other credit notes of the customer wait for it.
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_tenant::text || ':' || v_doc.customer_id::text, 0));

  -- It carries tax, and is in the currency, as its invoice was.
  IF v_doc.taxed <> v_invoice.taxed OR v_doc.prices_include_tax <> v_invoice.prices_include_tax OR v_doc.further_tax_excluded <> v_invoice.further_tax_excluded
     OR v_doc.currency <> v_invoice.currency OR v_doc.exchange_rate <> v_invoice.exchange_rate THEN
    RAISE EXCEPTION 'a credit note carries tax, and is in the currency, as its invoice was' USING ERRCODE = 'SE115';
  END IF;

  -- Line by line: no more than is left of what was invoiced, and exactly the invoice line's
  -- figures in the proportion of the quantity. What earlier credit notes took is what the
  -- posted ones say; this one is still a draft and is not among them.
  -- Each line's cost is the same share of what its goods cost when they left: on the invoice
  -- itself when it delivered them, on its delivery note otherwise.
  SELECT s.kind INTO v_source_kind FROM public.sales_documents s WHERE s.tenant_id = v_tenant AND s.id = v_invoice.source_document_id;
  FOR v_line IN
    SELECT l.id, l.quantity, l.base_quantity, l.unit_price, l.discount_amount, l.value, l.tax_amount, l.further_tax_amount, l.extra_tax_amount, i.code,
           o.id AS invoice_line_id, o.source_line_id AS delivery_line_id, o.quantity AS invoiced, o.base_quantity AS invoiced_base,
           o.value AS o_value, o.tax_amount AS o_tax, o.further_tax_amount AS o_further, o.extra_tax_amount AS o_extra,
           coalesce(g.quantity, 0) AS gone, coalesce(g.base_quantity, 0) AS gone_base, coalesce(g.value, 0) AS gone_value, coalesce(g.tax, 0) AS gone_tax,
           coalesce(g.further, 0) AS gone_further, coalesce(g.extra, 0) AS gone_extra, coalesce(g.cost, 0) AS gone_cost
    FROM public.sales_lines l
    JOIN public.sales_lines o ON o.tenant_id = l.tenant_id AND o.id = l.source_line_id AND o.document_id = v_invoice.id
    JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    LEFT JOIN LATERAL (
      SELECT sum(p.quantity) AS quantity, sum(p.base_quantity) AS base_quantity, sum(p.value) AS value, sum(p.tax_amount) AS tax,
             sum(p.further_tax_amount) AS further, sum(p.extra_tax_amount) AS extra, sum(p.returned_cost) AS cost
      FROM public.sales_lines p
      JOIN public.sales_documents pd ON pd.tenant_id = p.tenant_id AND pd.id = p.document_id
      WHERE p.tenant_id = v_tenant AND p.source_line_id = o.id AND pd.kind = 'credit_note' AND pd.status = 'submitted'
    ) g ON true
    WHERE l.tenant_id = v_tenant AND l.document_id = v_doc.id
    ORDER BY l.line_no
  LOOP
    v_lines := v_lines + 1;
    IF v_line.gone + v_line.quantity > v_line.invoiced THEN
      RAISE EXCEPTION 'more of % is being returned than was invoiced: % invoiced, % already returned, % on this credit note',
        v_line.code, v_line.invoiced, v_line.gone, v_line.quantity USING ERRCODE = 'SE114';
    END IF;
    v_upto := v_line.gone + v_line.quantity;
    v_value := app.credit_note_share(v_line.o_value, v_line.gone_value, v_upto, v_line.invoiced);
    v_tax := app.credit_note_share(v_line.o_tax, v_line.gone_tax, v_upto, v_line.invoiced);
    v_further := app.credit_note_share(v_line.o_further, v_line.gone_further, v_upto, v_line.invoiced);
    v_extra := app.credit_note_share(v_line.o_extra, v_line.gone_extra, v_upto, v_line.invoiced);
    -- The discount shown is what lies between the quantity at the price and what the line comes to.
    v_discount := greatest(round(v_line.quantity * v_line.unit_price, 2) - (CASE WHEN v_doc.prices_include_tax THEN v_value + v_tax + v_further ELSE v_value END), 0);
    IF v_line.value <> v_value OR v_line.tax_amount <> v_tax OR v_line.further_tax_amount <> v_further OR v_line.extra_tax_amount <> v_extra
       OR v_line.discount_amount <> v_discount THEN
      RAISE EXCEPTION 'the figures of % on this credit note are not those of its invoice', v_line.code USING ERRCODE = 'SE115';
    END IF;
    -- What these goods cost when they left, written on the line while the credit note is
    -- still a draft: once it is submitted its lines never change.
    IF v_source_kind = 'delivery' THEN
      SELECT abs(m.value), abs(m.quantity) INTO v_out_value, v_out_quantity FROM public.stock_moves m
        WHERE m.tenant_id = v_tenant AND m.source_type = 'delivery_note' AND m.source_id = v_invoice.source_document_id AND m.source_line_id = v_line.delivery_line_id
          AND m.reverses_move_id IS NULL AND m.quantity < 0;
    ELSE
      SELECT abs(m.value), abs(m.quantity) INTO v_out_value, v_out_quantity FROM public.stock_moves m
        WHERE m.tenant_id = v_tenant AND m.source_type = 'sales_invoice' AND m.source_id = v_invoice.id AND m.source_line_id = v_line.invoice_line_id
          AND m.reverses_move_id IS NULL AND m.quantity < 0;
    END IF;
    IF NOT FOUND OR v_out_quantity <> v_line.invoiced_base THEN
      RAISE EXCEPTION 'the invoice has no record of % leaving stock', v_line.code USING ERRCODE = 'SE121';
    END IF;
    v_cost := app.credit_note_share(v_out_value, v_line.gone_cost, v_line.gone_base + v_line.base_quantity, v_out_quantity);
    UPDATE public.sales_lines l SET returned_cost = v_cost WHERE l.tenant_id = v_tenant AND l.id = v_line.id;
  END LOOP;
  -- Every line was one of the invoice's (the lines' guard says so when each is written; asked again here).
  IF v_lines <> (SELECT count(*) FROM public.sales_lines l WHERE l.tenant_id = v_tenant AND l.document_id = v_doc.id) THEN
    RAISE EXCEPTION 'a line of a credit note takes back part of a line of its invoice' USING ERRCODE = 'SE120';
  END IF;

  -- Submitted first: the document's own guard checks it is whole, numbers it, copies the buyer
  -- and writes its audit row. From here on its lines cannot change.
  UPDATE public.sales_documents d SET status = 'submitted', submitted_by = v_user, updated_by = v_user, posted_txid = txid_current()
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id
    RETURNING d.* INTO v_doc;
  v_number := v_doc.number;

  -- The goods: those fit to sell go back into stock at their part of the line's cost; the
  -- damaged ones' part is written off.
  FOR v_line IN
    SELECT l.id, l.item_id, l.quantity, l.unit_factor, l.damaged_quantity, l.returned_cost
    FROM public.sales_lines l
    WHERE l.tenant_id = v_tenant AND l.document_id = v_doc.id
    -- Item by item, the same way round for every document, so two never wait on each other.
    ORDER BY l.item_id, l.line_no
  LOOP
    v_cost := v_line.returned_cost;
    v_cost_damaged := CASE WHEN v_line.damaged_quantity = v_line.quantity THEN v_cost ELSE round(v_cost * v_line.damaged_quantity / v_line.quantity, 2) END;
    v_good := (v_line.quantity - v_line.damaged_quantity) * v_line.unit_factor;
    IF v_good > 0 THEN
      PERFORM app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.document_date, v_good, v_cost - v_cost_damaged, 'credit_note', v_doc.id, v_line.id);
      v_restocked := v_restocked + (v_cost - v_cost_damaged);
    ELSE
      v_cost_damaged := v_cost;
    END IF;
    v_written_off := v_written_off + v_cost_damaged;
  END LOOP;

  -- As much as is still unpaid of the invoice is settled; the rest is the customer's credit.
  SELECT r.total - r.settled INTO v_outstanding FROM app.receivable_items(v_tenant, v_doc.customer_id) r WHERE r.kind = 'invoice' AND r.id = v_invoice.id;
  v_applied := least(v_doc.total, greatest(coalesce(v_outstanding, 0), 0));
  v_excess := v_doc.total - v_applied;

  -- A credit note for nothing, of goods that cost nothing, leaves no journal.
  IF v_doc.total > 0 OR v_restocked > 0 OR v_written_off > 0 THEN
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, v_doc.document_date, 'credit_note', v_doc.id, v_number, left('Credit note to ' || v_doc.buyer_name || ' for invoice ' || v_invoice.number, 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    IF v_doc.value_total > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'sales'), v_doc.value_total, 0, 'Sales returned');
    END IF;
    IF v_doc.tax_total + v_doc.extra_tax_total > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'output_tax'), v_doc.tax_total + v_doc.extra_tax_total, 0, 'Sales tax on goods returned');
    END IF;
    IF v_doc.further_tax_total > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'further_tax'), v_doc.further_tax_total, 0, 'Further tax on goods returned');
    END IF;
    IF v_applied > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'ar'), 0, v_applied, 'Credit note ' || v_number || ' against invoice ' || v_invoice.number, v_doc.customer_id);
    END IF;
    IF v_excess > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'customer_advances'), 0, v_excess, 'Credit note ' || v_number || ': credit left with the customer', v_doc.customer_id);
    END IF;
    IF v_restocked > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'inventory'), v_restocked, 0, 'Returned goods back in stock');
    END IF;
    IF v_written_off > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'stock_adjustment'), v_written_off, 0, 'Returned goods damaged, written off');
    END IF;
    IF v_restocked + v_written_off > 0 THEN
      v_line_no := v_line_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_line_no, app.control_account(v_tenant, 'cogs'), 0, v_restocked + v_written_off, 'Cost of the goods returned');
    END IF;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', v_doc.document_date, 'source', 'credit_note', 'sourceId', v_doc.id, 'number', v_number, 'lines', v_line_no, 'total', (v_doc.total + v_restocked + v_written_off)::text));
  END IF;
  IF v_applied > 0 THEN
    INSERT INTO public.credit_note_allocations (tenant_id, credit_note_id, invoice_id, amount, allocated_on, journal_id, created_by)
      VALUES (v_tenant, v_doc.id, v_invoice.id, v_applied, v_doc.document_date, v_journal, v_user);
  END IF;
  PERFORM app.require_not_overpaid(v_tenant, v_doc.customer_id);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'credit_note.post', 'sales_document', v_doc.id,
      jsonb_build_object('number', v_number, 'invoice', v_invoice.number, 'date', v_doc.document_date, 'total', v_doc.total::text,
        'setAgainstInvoice', v_applied::text, 'leftAsCredit', v_excess::text, 'backInStock', v_restocked::text, 'writtenOff', v_written_off::text));
  RETURN QUERY SELECT v_number, v_journal, v_applied, v_excess;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_credit_note(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_credit_note(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: setting a credit note's credit against other invoices ─────────────────────────
-- What a posted credit note did not set against its own invoice is the customer's credit. Part
-- or all of it is set against invoices later: p_allocations is a list of
--   {"invoice_id": ..., "amount": ...}  or  {"opening_balance_id": ..., "amount": ...}
-- Each becomes a row that counts from p_date, with a journal of its own:
--
--   debit   Advances from customers (the customer)
--   credit  Trade receivables (the customer)
--
-- For the owner and an accountant: it is settling what a customer owes, not recording a return.
-- Refused: more than is left of the credit (SE118), an invoice that cannot take it (SE102).
-- Returns how many invoices it was set against.
CREATE FUNCTION app.apply_credit_note(p_credit_note uuid, p_date date, p_allocations jsonb) RETURNS integer
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.sales_documents%ROWTYPE;
  v_left numeric;
  v_asked numeric;
  v_wrong text;
  v_row record;
  v_id uuid;
  v_journal uuid;
  v_count integer := 0;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot set a customer''s credit against invoices' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sales documents are written in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  -- Held until the transaction ends: two people setting the same credit against invoices take their turn.
  SELECT d.* INTO v_doc FROM public.sales_documents d
    WHERE d.tenant_id = v_tenant AND d.id = p_credit_note AND d.kind = 'credit_note'
    FOR NO KEY UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope))) OR v_doc.status <> 'submitted' THEN
    RAISE EXCEPTION 'no such posted credit note in this company' USING ERRCODE = 'SE112';
  END IF;
  IF p_date IS NULL OR p_date < v_doc.document_date THEN
    RAISE EXCEPTION 'credit is set against an invoice on or after the day of its credit note' USING ERRCODE = 'SE108';
  END IF;
  IF p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE111';
  END IF;
  IF p_allocations IS NULL OR jsonb_typeof(p_allocations) <> 'array' OR jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'name between 1 and 200 invoices' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_allocations) AS x(value)
    WHERE jsonb_typeof(x.value) <> 'object'
       OR (nullif(x.value->>'invoice_id', '') IS NULL) = (nullif(x.value->>'opening_balance_id', '') IS NULL)
       OR (x.value->>'amount') IS NULL
       OR (x.value->>'amount')::numeric = 'NaN'::numeric OR (x.value->>'amount')::numeric <= 0 OR (x.value->>'amount')::numeric >= 1e16
       OR (x.value->>'amount')::numeric <> round((x.value->>'amount')::numeric, 4)
  ) OR (
    -- Compared as ids, not as text: the same id in capitals or in braces is the same invoice.
    SELECT count(*) <> count(DISTINCT coalesce(nullif(x.value->>'invoice_id', '')::uuid, nullif(x.value->>'opening_balance_id', '')::uuid))
    FROM jsonb_array_elements(p_allocations) AS x(value)
  ) THEN
    RAISE EXCEPTION 'each invoice is named once, with an amount above nothing to at most four decimals' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  PERFORM pg_advisory_xact_lock(hashtextextended('credit:' || v_tenant::text || ':' || v_doc.customer_id::text, 0));
  -- The opening balances named stay as they are until the transaction ends.
  PERFORM 1 FROM public.opening_entries e
    WHERE e.tenant_id = v_tenant AND e.id IN (
      SELECT b.opening_entry_id FROM jsonb_array_elements(p_allocations) AS x(value)
      JOIN public.opening_balances b ON b.tenant_id = v_tenant AND b.id = nullif(x.value->>'opening_balance_id', '')::uuid)
    FOR SHARE;

  SELECT v_doc.total - coalesce(sum(a.amount), 0) INTO v_left FROM public.credit_note_allocations a
    WHERE a.tenant_id = v_tenant AND a.credit_note_id = v_doc.id;
  SELECT sum((x.value->>'amount')::numeric) INTO v_asked FROM jsonb_array_elements(p_allocations) AS x(value);
  IF v_asked > v_left THEN
    RAISE EXCEPTION '% is left of this credit, and % was asked for', v_left, v_asked USING ERRCODE = 'SE118';
  END IF;
  SELECT coalesce(i.number, 'an invoice that is not this customer''s') INTO v_wrong
    FROM jsonb_array_elements(p_allocations) AS x(value)
    LEFT JOIN app.receivable_items(v_tenant, v_doc.customer_id) i
      ON ((i.kind = 'invoice' AND i.id = nullif(x.value->>'invoice_id', '')::uuid) OR (i.kind = 'opening' AND i.id = nullif(x.value->>'opening_balance_id', '')::uuid))
     AND (v_scope IS NULL OR i.branch_id = ANY (v_scope))
    WHERE i.id IS NULL OR (x.value->>'amount')::numeric > i.total - i.settled OR i.document_date > p_date
    LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'the credit cannot pay that much of %: it is not a posted invoice of this customer dated on or before that day, or less is left to pay', v_wrong USING ERRCODE = 'SE102';
  END IF;

  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  FOR v_row IN
    SELECT nullif(x.value->>'invoice_id', '')::uuid AS invoice_id, nullif(x.value->>'opening_balance_id', '')::uuid AS opening_balance_id, (x.value->>'amount')::numeric AS amount, x.ordinality
    FROM jsonb_array_elements(p_allocations) WITH ORDINALITY AS x(value, ordinality)
    ORDER BY x.ordinality
  LOOP
    v_id := gen_random_uuid();
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, p_date, 'credit_application', v_id, NULL, left('Credit of credit note ' || v_doc.number || ' set against an invoice', 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, customer_id)
      VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, 'customer_advances'), v_row.amount, 0, 'Credit of credit note ' || v_doc.number, v_doc.customer_id),
             (v_tenant, v_journal, 2, app.control_account(v_tenant, 'ar'), 0, v_row.amount, 'Credit of credit note ' || v_doc.number, v_doc.customer_id);
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', p_date, 'source', 'credit_application', 'sourceId', v_id, 'number', NULL, 'lines', 2, 'total', v_row.amount::text));
    INSERT INTO public.credit_note_allocations (id, tenant_id, credit_note_id, invoice_id, opening_balance_id, amount, allocated_on, journal_id, created_by)
      VALUES (v_id, v_tenant, v_doc.id, v_row.invoice_id, v_row.opening_balance_id, v_row.amount, p_date, v_journal, v_user);
    v_count := v_count + 1;
  END LOOP;
  PERFORM app.require_not_overpaid(v_tenant, v_doc.customer_id);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'credit_note.apply', 'sales_document', v_doc.id,
      jsonb_build_object('number', v_doc.number, 'date', p_date, 'invoices', v_count, 'setAgainstInvoices', v_asked::text, 'leftOfCredit', (v_left - v_asked)::text));
  RETURN v_count;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.apply_credit_note(uuid, date, jsonb) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.apply_credit_note(uuid, date, jsonb) TO app_runtime;
--> statement-breakpoint

-- What one credit note has been set against, row by row, with the number and date of each
-- invoice, for whoever may read the credit note: the sales team does not otherwise read the
-- opening balances. To a member who may not read the credit note it says nothing. Which
-- invoice a row settled is said only to a member who may read that invoice: not another
-- branch's to a member limited to some branches, not a colleague's to a salesperson, and not
-- the opening balances to either; they see the amount and the day. `later` is true for credit
-- set against an invoice after the credit note was posted.
CREATE FUNCTION app.credit_note_settled(p_credit_note uuid)
  RETURNS TABLE (id uuid, kind text, target_id uuid, number text, document_date date, amount numeric, allocated_on date, later boolean)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson') OR NOT EXISTS (
    SELECT 1 FROM public.sales_documents n
    WHERE n.tenant_id = v_tenant AND n.id = p_credit_note AND n.kind = 'credit_note'
      AND (v_role <> 'salesperson' OR n.created_by = v_user OR n.salesperson_id IS NOT DISTINCT FROM v_user)
      AND (v_scope IS NULL OR n.branch_id = ANY (v_scope))
  ) THEN
    RETURN;
  END IF;
  RETURN QUERY
    SELECT a.id, CASE WHEN a.invoice_id IS NOT NULL THEN 'invoice' ELSE 'opening' END,
           CASE WHEN s.shown THEN coalesce(a.invoice_id, a.opening_balance_id) END,
           CASE WHEN s.shown THEN coalesce(d.number, b.document_number) END,
           CASE WHEN s.shown THEN coalesce(d.document_date, b.document_date) END,
           a.amount, a.allocated_on, j.source_type = 'credit_application'
    FROM public.credit_note_allocations a
    JOIN public.journals j ON j.tenant_id = a.tenant_id AND j.id = a.journal_id
    LEFT JOIN public.sales_documents d ON d.tenant_id = a.tenant_id AND d.id = a.invoice_id
    LEFT JOIN public.opening_balances b ON b.tenant_id = a.tenant_id AND b.id = a.opening_balance_id
    CROSS JOIN LATERAL (
      SELECT coalesce(
        (v_scope IS NULL OR d.branch_id = ANY (v_scope))
        AND (v_role <> 'salesperson' OR d.created_by = v_user OR d.salesperson_id = v_user), false) AS shown
    ) s
    WHERE a.tenant_id = v_tenant AND a.credit_note_id = p_credit_note
    ORDER BY a.created_at, a.allocated_on, a.id;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.credit_note_settled(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.credit_note_settled(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: opening balances that credit has been set against stay ────────────────────────
-- As for receipts (drizzle/0022_receipts.sql): reversing the opening balances starts a new
-- draft with new lines, and credit set against one of the old lines would be left settling an
-- invoice that is no longer in the books. A credit note is never cancelled, so opening
-- balances with credit set against them stay. A trigger of this step's own on the opening
-- entries; the entry's own guard is unchanged.
CREATE FUNCTION app.check_opening_not_credited() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  -- Asked of what is committed now. A transaction reading an older picture of the database
  -- would not see credit, or a receipt, set against these balances a moment ago, so it is not
  -- let in. (This stands guard for the same check of drizzle/0022_receipts.sql as well: both
  -- are asked of every change to an opening entry.)
  IF OLD.status = 'posted' AND NEW.status <> 'posted' AND current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'opening balances are reversed in read committed transactions' USING ERRCODE = 'SE056';
  END IF;
  IF OLD.status = 'posted' AND NEW.status <> 'posted' AND EXISTS (
    SELECT 1 FROM public.credit_note_allocations a
    JOIN public.opening_balances b ON b.tenant_id = a.tenant_id AND b.id = a.opening_balance_id
    WHERE a.tenant_id = OLD.tenant_id AND b.opening_entry_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'a credit note''s credit has been set against these opening balances; they can no longer be reversed' USING ERRCODE = 'SE119';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_opening_not_credited() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER opening_entries_credit_allocated
  BEFORE UPDATE ON public.opening_entries
  FOR EACH ROW EXECUTE FUNCTION app.check_opening_not_credited();
--> statement-breakpoint
ALTER TABLE public.opening_entries ENABLE ALWAYS TRIGGER opening_entries_credit_allocated;
